-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 20
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 20 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 20', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 20 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-20.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique quando um banco está realmente pronto para ser entregue.', 0.2, 'Quando **outra pessoa** (o back-end, o DBA, a próxima equipe) consegue **entender, recriar e usar** o banco **sem perguntar** ao grupo que o fez.', 'Nota cheia (0,2): outra pessoa + entender/recriar/usar sem perguntar. Metade (0,1): só "funciona no computador do grupo" com a ideia de usar. Zero (0): sem relação.'),
      (v_atividade, 1, 2, 'Liste as peças da documentação técnica do banco e diga em uma frase para que serve cada uma.', 0.4, '**Escopo** (objetivo, requisitos, entra/não entra); **DER** (modelo final); **dicionário de dados** (cada coluna com tipo, formato, domínio); **cronograma** (planejado × realizado); **fluxograma** (processo da matrícula e pontos do banco); **scripts numerados** (recriam o banco); **matriz de acesso** (quem pode S, I, U, D); **README/guia de instalação** (recriar, conectar e testar).', 'Nota cheia (0,4): pelo menos seis peças com a função certa. Metade (0,2): três a cinco peças, ou peças sem a função. Zero (0): duas ou menos.'),
      (v_atividade, 1, 3, 'Explique por que o guia de instalação (README) é a peça que a empresa vai abrir primeiro e o que ele precisa explicar.', 0.4, 'Porque é o **ponto de partida** de quem não fez o banco: explica **como recriar do zero** (ordem dos scripts e comandos), **como conectar** (login app_escola e variável de ambiente) e **como testar** (conferência e testes); sem ele, a empresa teria de perguntar ao grupo.', 'Nota cheia (0,4): recriar + conectar + testar. Metade (0,2): dois dos três. Zero (0): um ou nenhum.'),
      (v_atividade, 2, 1, 'Diga qual documento é a referência para conferir a entrega final e o que ele contém.', 0.2, 'O **documento de escopo** (aula 5): objetivo, partes interessadas, o que **entra** e o que **não entra**, **requisitos de dados**, entregas e prazos, premissas e riscos.', 'Nota cheia (0,2): escopo + pelo menos três itens. Metade (0,1): só "escopo". Zero (0): outro documento.'),
      (v_atividade, 2, 2, 'Classifique as situações 1 e 2 e diga o que fazer com cada uma.', 0.4, '(1) requisito sem tabela = **pendência**: criar o que falta (ex.: coluna ou tabela de responsável) e registrar no cronograma; (2) tabela sem requisito = **excesso** (ou mudança de escopo sem registro): retirar da entrega ou registrar a mudança e pedir aprovação.', 'Nota cheia (0,4): as duas classificações + o que fazer. Metade (0,2): classificações sem a ação, ou só uma completa. Zero (0): trocadas.'),
      (v_atividade, 2, 3, 'Explique como uma mudança de escopo deve ser tratada para que a tabela "brinde" pudesse fazer parte da entrega.', 0.4, 'Registrar o **pedido**, o **impacto** (tempo, tabelas, custo) e obter a **aprovação** do cliente; só então a tabela entra no escopo, no cronograma e na rastreabilidade.', 'Nota cheia (0,4): pedido + impacto + aprovação. Metade (0,2): só um ou dois. Zero (0): "cria e pronto".'),
      (v_atividade, 3, 1, 'Diga quais informações o dicionário de dados traz para cada coluna.', 0.2, '**Nome padronizado**, **tipo**, **formato**, **obrigatoriedade** (NOT NULL), **domínio** (valores aceitos) e **descrição**.', 'Nota cheia (0,2): pelo menos quatro. Metade (0,1): duas ou três. Zero (0): uma ou nenhuma.'),
      (v_atividade, 3, 2, 'Escreva a linha correta do dicionário para a coluna data_pagamento da tabela parcela.', 0.4, 'Tabela **parcela** · coluna **data_pagamento** · tipo **date** · formato AAAA-MM-DD · **opcional** (nula enquanto não paga) · descrição: **data em que a parcela foi paga**; só o financeiro altera (aula 19).', 'Nota cheia (0,4): nome certo + date + opcional + descrição. Metade (0,2): nome e tipo certos sem obrigatoriedade/descrição. Zero (0): mantém "pago_em" ou tipo texto.'),
      (v_atividade, 3, 3, 'Explique o problema de entregar o dicionário desatualizado em relação ao SQL.', 0.4, 'A documentação **deixa de bater com o banco**: o back-end escreve consultas com o nome ou o tipo errado, tem **erro** e perde a confiança no documento; o dicionário é o que **guia o SQL** e precisa ser atualizado junto.', 'Nota cheia (0,4): não bate + consequência. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 4, 1, 'Explique por que os scripts precisam ser numerados.', 0.2, 'Porque **a ordem de execução importa**: a tabela de referência precisa existir antes da **chave estrangeira**, e as tabelas antes do **GRANT** e das rotinas.', 'Nota cheia (0,2): ordem + exemplo de dependência. Metade (0,1): só "por causa da ordem". Zero (0): estética.'),
      (v_atividade, 4, 2, 'Renomeie os sete scripts com números na ordem correta de execução, dizendo o conteúdo de cada um.', 0.4, '**01-banco-e-usuario.sql** (banco e login app_escola); **02-tabelas.sql** (CREATE TABLE); **03-chaves-e-restricoes.sql** (PK, FK, UNIQUE, CHECK); **04-dados-iniciais.sql** (INSERT); **05-consultas.sql** (relatórios); **06-procedimentos-e-triggers.sql** (matricular e triggers); **07-seguranca.sql** (grupos, GRANT, visão, auditoria).', 'Nota cheia (0,4): os sete na ordem com o conteúdo. Metade (0,2): ordem com uma ou duas trocas, ou sem o conteúdo. Zero (0): segurança antes das tabelas ou ordem sem sentido.'),
      (v_atividade, 4, 3, 'Cite três boas práticas que todo script da entrega deve seguir e explique uma delas.', 0.4, '**Comentário no início** (o que faz, dependência, quem alterou); **idempotente** (IF NOT EXISTS, CREATE OR REPLACE); **transação** (BEGIN/COMMIT: se falhar, nada fica pela metade); **sem senha real**; **versionado no Git**. Explicação de uma delas.', 'Nota cheia (0,4): três práticas + explicação correta de uma. Metade (0,2): três sem explicação, ou duas com explicação. Zero (0): uma ou nenhuma.'),
      (v_atividade, 5, 1, 'Explique por que o banco deve ser recriado do zero num banco limpo antes da entrega.', 0.2, 'O banco do próprio computador pode estar **"remendado"** (comandos rodados à mão, fora dos scripts) e **esconder erros**; só a recriação **num banco limpo** prova que os **scripts sozinhos** criam o banco.', 'Nota cheia (0,2): remendado/esconde erro + só os scripts. Metade (0,1): só um. Zero (0): sem relação.'),
      (v_atividade, 5, 2, 'Escreva os comandos do psql que executam, na ordem, os scripts 02-tabelas.sql e 03-chaves-e-restricoes.sql no banco escola_db, parando no primeiro erro.', 0.4, 'psql -U postgres -d escola_db **-v ON_ERROR_STOP=1** -f 02-tabelas.sql e depois psql -U postgres -d escola_db **-v ON_ERROR_STOP=1** -f 03-chaves-e-restricoes.sql (nessa ordem).', 'Nota cheia (0,4): os dois comandos com -d escola_db, -f e ON_ERROR_STOP, na ordem. Metade (0,2): sem ON_ERROR_STOP, ou ordem trocada. Zero (0): comandos sem relação.'),
      (v_atividade, 5, 3, 'Explique o que a opção -v ON_ERROR_STOP=1 evita e como executar um arquivo de dentro do psql.', 0.4, 'Faz o psql **parar no primeiro erro**, em vez de **seguir e esconder** o problema (o 03 falhou e os outros rodaram por cima). Dentro do psql, **\i 02-tabelas.sql** executa o arquivo.', 'Nota cheia (0,4): para no primeiro erro + \i. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 6, 1, 'Explique o que é a matriz de rastreabilidade.', 0.2, 'É uma tabela que **liga cada requisito do escopo** ao que o **atende no banco** (tabela, restrição, rotina, permissão) e ao **script** onde está.', 'Nota cheia (0,2): requisito → banco → script. Metade (0,1): sem o script ou sem o requisito. Zero (0): confunde com cronograma.'),
      (v_atividade, 6, 2, 'Escreva as linhas da matriz para R1, R2, R4 e R6, com o que atende cada requisito no banco e o script.', 0.4, 'R1 → **UNIQUE (cpf)** em aluno, scripts 02/03; R2 → **procedimento matricular** (conta e barra a 26ª), script 06; R4 → **trigger de validação** da parcela, script 06; R6 → **GRANT SELECT (id_aluno, nome) ON aluno** ao grupo do financeiro, script 07.', 'Nota cheia (0,4): os quatro com peça e script. Metade (0,2): dois ou três certos, ou os quatro sem script. Zero (0): um ou nenhum.'),
      (v_atividade, 6, 3, 'Explique como a matriz de rastreabilidade ajuda a encontrar pendências e excessos na entrega.', 0.4, 'Requisito **sem linha** (nada no banco o atende) é **pendência**; tabela ou rotina que **não aparece** em nenhuma linha é **excesso** ou mudança de escopo sem registro. A matriz também prova ao cliente que **nada ficou de fora**.', 'Nota cheia (0,4): pendência + excesso. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 7, 1, 'Diga os comandos do psql que listam as tabelas do banco e que mostram as colunas e restrições da tabela matricula.', 0.2, '**\dt** lista as tabelas; **\d matricula** mostra colunas, tipos e restrições.', 'Nota cheia (0,2): os dois. Metade (0,1): um. Zero (0): nenhum.'),
      (v_atividade, 7, 2, 'Descreva três testes da conferência final (estrutura ou dados, regra do negócio e permissões), com o comando ou a ação e o resultado esperado de cada um.', 0.4, 'Ex.: (1) SELECT count(*) FROM curso; → a quantidade de cursos dos dados iniciais; (2) CALL matricular(...) numa turma com 25 alunos → **erro** com a mensagem do RAISE EXCEPTION; (3) login do financeiro: SELECT cpf FROM aluno; → **permission denied**. Outros testes válidos: gravar FK inexistente (erro), alterar a nota e ver o histórico, alterar parcela e ver a auditoria, \dp.', 'Nota cheia (0,4): três testes de tipos diferentes com ação e resultado esperado. Metade (0,2): dois, ou três sem o resultado esperado. Zero (0): um ou nenhum.'),
      (v_atividade, 7, 3, 'Explique o que cada linha do relatório de testes registra e por que um erro do banco pode ser o resultado esperado.', 0.4, 'Cada linha registra **o que foi testado**, o **resultado esperado** e o **resultado obtido**. O erro pode ser o esperado porque prova que a **regra funciona** (FK, CHECK, turma cheia, permission denied).', 'Nota cheia (0,4): as três colunas + erro esperado. Metade (0,2): só uma das partes. Zero (0): sem relação.'),
      (v_atividade, 8, 1, 'Escreva o comando que gera o backup do banco escola_db no formato custom.', 0.2, 'pg_dump -U postgres **-Fc** -d escola_db -f escola_db_entrega.dump', 'Nota cheia (0,2): pg_dump com -Fc e o banco. Metade (0,1): pg_dump sem -Fc (formato texto). Zero (0): pg_restore ou outro.'),
      (v_atividade, 8, 2, 'Escreva os comandos que criam o banco escola_db_teste, restauram o backup nele e conferem a quantidade de alunos.', 0.4, 'createdb -U postgres escola_db_teste; pg_restore -U postgres -d escola_db_teste escola_db_entrega.dump; psql -U postgres -d escola_db_teste -c "SELECT count(*) FROM aluno;"', 'Nota cheia (0,4): os três passos em outro banco. Metade (0,2): restaura sem conferir, ou restaura no banco original. Zero (0): nenhum passo certo.'),
      (v_atividade, 8, 3, 'Explique por que o backup só vale depois da restauração e por que o arquivo não deve ir para o Git.', 0.4, 'Backup **nunca restaurado não é garantia** (disponibilidade): só a restauração prova que o arquivo serve. O arquivo tem **dados pessoais** (CPF etc.): no **Git** ficaria exposto a quem acessa o repositório (confidencialidade, LGPD); fica num lugar com **acesso restrito**.', 'Nota cheia (0,4): as duas explicações. Metade (0,2): só uma. Zero (0): nenhuma.'),
      (v_atividade, 9, 1, 'Diga com qual login o back-end deve se conectar e onde fica a string de conexão.', 0.2, 'Login **app_escola** (só o que o sistema precisa); string de conexão numa **variável de ambiente**.', 'Nota cheia (0,2): os dois. Metade (0,1): um. Zero (0): postgres ou senha no código.'),
      (v_atividade, 9, 2, 'Escreva o exemplo da variável de ambiente DATABASE_URL e liste o que entra no "contrato" do banco entregue ao back-end.', 0.4, 'DATABASE_URL=**postgresql://app_escola:<senha>@servidor:5432/escola_db**. Contrato: **tabelas e colunas** (dicionário), **visões** (vw_matriculas_por_turma), **procedimentos** (CALL matricular(id_aluno, id_turma)) e as **mensagens de erro** que devolvem.', 'Nota cheia (0,4): URL com app_escola + pelo menos três itens do contrato. Metade (0,2): só a URL ou só o contrato. Zero (0): URL com postgres e sem contrato.'),
      (v_atividade, 9, 3, 'Explique por que a senha do postgres não é entregue e o que o back-end deve fazer quando o banco devolve um erro de regra (por exemplo, a turma cheia).', 0.4, 'O postgres tem **poder total**: entregar a senha fere o **menor privilégio** e, se vazar, o invasor pode tudo. Quando o banco devolve um erro de regra, o back-end deve **tratar o erro** e mostrar uma **mensagem clara** ao usuário (ex.: "turma sem vagas"), sem desligar a regra do banco.', 'Nota cheia (0,4): menor privilégio + tratar o erro. Metade (0,2): só um. Zero (0): entrega a senha ou ignora o erro.'),
      (v_atividade, 10, 1, 'Diga como a sugestão de renomear a tabela deve ser registrada pelo grupo.', 0.2, 'Uma linha no registro da revisão com a **sugestão**, a **decisão** (aceita ou não), o **motivo** e **quem ajusta**.', 'Nota cheia (0,2): os quatro campos (aceitar três). Metade (0,1): só a sugestão e a decisão. Zero (0): não registrar.'),
      (v_atividade, 10, 2, 'Justifique tecnicamente as escolhas 1 e 2.', 0.4, '(1) A parcela é **entidade fraca**: só existe dentro da matrícula; a chave **(id_matricula, numero)** identifica a parcela pela dona e **impede parcela repetida** na mesma matrícula. (2) O limite precisa **contar as matrículas** da turma (consulta em outras linhas); um **CHECK só olha a própria linha**, por isso a regra fica no **procedimento** (com a trava da aula 17).', 'Nota cheia (0,4): as duas justificativas técnicas. Metade (0,2): só uma. Zero (0): "porque sim" ou justificativas erradas.'),
      (v_atividade, 10, 3, 'Explique as atitudes esperadas do revisor e do autor na revisão cruzada e decida, com justificativa, se aceita a troca de matricula para inscricao.', 0.4, '**Revisor** pergunta em vez de acusar, aponta onde está o problema e sugere; **autor** escuta, confere nos requisitos e **aceita ou justifica**. Decisão (qualquer uma vale com base técnica): ex.: **não aceitar**, porque "matricula" é o termo do **escopo** e do cliente e já está no dicionário, nos scripts, no procedimento e na matriz de acesso — renomear agora geraria retrabalho e risco; ou **aceitar**, registrando e ajustando todas as peças.', 'Nota cheia (0,4): atitudes dos dois + decisão justificada com requisito/impacto. Metade (0,2): só as atitudes ou só a decisão justificada. Zero (0): decisão sem justificativa e sem atitudes.');
end $$;
